    const film = [];
    const insert = (caption, beats, role, opts={}) => {
      if (!beats.length || film.length >= 5) return;
      film.push({date:beats[0].date, sentence:caption, scene:'neutral', art:beats[0].art, beats,
        role, silent:false, holdMs: opts.holdMs ?? 650, evidence:opts.evidence ?? []});
    };
    const choose = (rows,n) => {
      if (rows.length <= n) return rows;
      const indices = [...new Set(Array.from({length:n},(_,j) => Math.round(j*(rows.length-1)/(n-1))))];
      return indices.map(i => rows[i]);
    };
